def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v2 == 0:
        return None

    value = v1 / v2

    return {
        "value": value,
        "trace": {
            "remaining_discount_2017": v1,
            "remaining_discount_2016": v2,
            "ratio": value,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
